        let y0: i32 = crate::port::cells_at(fl, (f * 6) + 1);
        let x1: i32 = crate::port::cells_at(fl, (f * 6) + 2);
        let y1: i32 = crate::port::cells_at(fl, (f * 6) + 3);
        let nb: i32 = tb_rows_of(bd, 6);
